import pathlib,json,csv,hashlib,datetime
P=pathlib.Path(__file__).resolve().parent
L=json.loads((P/'S2_2010_RUN_LOG.txt').read_text());Q=json.loads((P/'QA_checks.json').read_text());assert L['exit_code']==0 and all(x['pass'] for x in Q)
rows=list(csv.DictReader((P/'S2_Organizational_Participation_2010_DIRECT_v1.csv').open()))
def write(n,rs):
 with (P/n).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
rawurl='https://www2.census.gov/programs-surveys/cps/datasets/2010/supp/nov10pub_civic.dat.gz';docurl='https://www2.census.gov/programs-surveys/cps/techdocs/cpsnov10c.pdf'
urls={'nov10pub_civic.dat.gz':rawurl,'cpsnov10c.pdf':docurl,'variables.json':'https://api.census.gov/data/2010/cps/civic/nov/variables.json','verified_variables.json':'https://api.census.gov/data/2010/cps/civic/nov/variables.json'}
manifest=[{'file':n,'source_url':urls[n],'sha256':v['sha256'],'bytes':v['bytes'],'storage':'Official download manifest; source bytes available in local full package' if n!='verified_variables.json' else 'Repository selected metadata','input_verified_at_utc':L['start_utc'],'note':'HTTP200 downloaded; immutable hash verified at execution start; credential-free source'} for n,v in L['inputs'].items()]
for r in L['api_requests']:manifest.append({'file':'API_'+r['variable']+'.json','source_url':r['url_without_key'],'sha256':r['sha256'],'bytes':r['bytes'],'storage':'Repository exact API response bytes','input_verified_at_utc':r['end_utc'],'note':'Authenticated weighted count QA; credential omitted'})
write('S2_2010_SOURCE_MANIFEST.csv',manifest)
write('S2_2010_PROVENANCE_v1.csv',[{'state':r['state'],'state_fips':r['state_fips'],'year':2010,'observation_type':'DIRECT','run_id':L['run_id'],'input_file':'nov10pub_civic.dat.gz','input_sha256':L['inputs']['nov10pub_civic.dat.gz']['sha256'],'source':rawurl,'weight':'PWNRWGT','universe':'civilian noninstitutional age18+;PRSUPINT1;all MIS1-8;self/proxy','missing_rule':'any Yes1;all five No0;otherwise missing','se_status':'UNAVAILABLE_DESIGN_BASED','code_sha256':L['code_sha256'],'output_sha256':L['outputs']['S2_Organizational_Participation_2010_DIRECT_v1.csv']} for r in rows])
lines=['# S2 2010 Direct Extraction QA','',f"Run ID: {L['run_id']}",f"Execution UTC: {L['start_utc']} — {L['end_utc']}",f"Code SHA256: {L['code_sha256']}",'Exit code: 0. 29/29 execution checks PASS. 50/50 direct state estimates. DC excluded from canonical.','Respondents: 76084 supplement interviews (50 states+DC); canonical n_unweighted is classified Yes/No respondent count, not all eligible interviews.','Units: s2_participation is a proportion (0–1); s2_se would use the same unit.','', '## Measurement and continuity','2010 includes all eight CPS rotation groups, civilian noninstitutional household people age18+, supplement interview1. Self or proxy response permitted; reporter may be a household member age15+. 2009 used outgoing MIS4/8 and reporterage18+. Canonical missing rule: any Yes identifies a participant even if another answer is unknown; all five No identifies nonparticipation; otherwise missing. No negative response is imputed as No.','Questionnaire introduction changed; categories, weight name/purpose and response/missing codes are SAME. Universe CHANGED. Full six-dimension audit is preserved in the continuity CSV. The comparison uses official 2009/2010 documents; 2009 estimates were not rerun.','', '## Weight and external benchmarks','PWNRWGT is expressly instructed in 2010 Attachment3. Raw weights at981–990 have four implied decimals; the scaling was validated by five API tables, 102 cells per item, 510 cells total, within0.51-person server rounding.','Official Attachment13 Q5A frequencies match exactly. Attachment16 school/sports Yes totals match within500 persons for rounding. The published population229690000 is reproduced by PWSSWGT over all adult civilians:229690388.5952. The supplement-response PWNRWGT sum is230442932.0064. These are different bases and are not substituted for one another. Published percentages using the population base are not falsely compared with canonical valid-response percentages.','An initial population check using PWNRWGT failed; investigation reconciled the published illustration with the basic final-weight population. Attempt1 code, log and QA are retained for transparency.','No independent same-year same-denominator union benchmark was verified; this is not a reason to discard the direct observations.','', '## SE assessment','SE coverage:0/50. The inspected Census2010 Civic download page offers the supplement data but no2010 replicate-weight download; API metadata contains no replicate-weight series. This is a bounded source inspection, not a claim that replicate weights cannot exist elsewhere. No2010-specific replicate count, formula or scaling factor was established.','2010 Attachment16 supplies generalized percentage SE: sqrt[b*p*(100-p)/y], where p is in percent and y is the population base; Table4 total b=4687. The document also discusses replication underlying those generalized parameters. No independently verified state-domain applicability/calibration for the requested valid-response union indicator was established, so this formula was not forced into s2_se. Blank SE means unavailable, never zero. No simple-binomial, adjacent-year or S3 variance formula was used.','Census source: '+docurl,'2010 download page: https://www.census.gov/data/datasets/time-series/demo/cps/cps-supp_cps-repwgt/cps-civic.2010.html','', '## Actual checks','| Check | Result | Evidence |','|---|---|---|']
for q in Q:lines.append('| '+q['name']+' | '+('PASS' if q['pass'] else 'FAIL')+' | '+json.dumps(q['detail'],ensure_ascii=False).replace('|','/')+' |')
lines+=['','## Scope and preservation','2010-only extraction; no interpolation, model estimate or adjacent-year substitution. No GitHub Actions or workflow was invoked.','Source manifest preserves exact official raw-download URL, byte count and SHA256. Small API responses are saved as exact source bytes. Full raw source and documentation are included in the local downloadable package; repository preservation uses the expressly allowed original-download manifest.','Census credentials are read only from CENSUS_API_KEY by execution code. No credential appears in sources, logs, tables, provenance, manifests or responses.','STATUS: 2010 COMPLETE for direct observations and declared QA/SE coverage — STOPPED BEFORE2011. SE availability remains0/50.']
(P/'S2_2010_QA_v1.md').write_text('\n'.join(lines)+'\n')
# Reconcile report with actual logs, code and output bytes.
assert len(rows)==50 and len(set(r['state_fips'] for r in rows))==50
assert all(r['year']=='2010' and r['observation_type']=='DIRECT' and r['state_fips']!='11' and not r['s2_se'] for r in rows)
for n,h in L['outputs'].items():assert hashlib.sha256((P/n).read_bytes()).hexdigest()==h
assert hashlib.sha256((P/'extract_2010.py').read_bytes()).hexdigest()==L['code_sha256']
for n,v in L['inputs'].items():assert hashlib.sha256((P/n).read_bytes()).hexdigest()==v['sha256']
for r in L['api_requests']:assert hashlib.sha256((P/('API_'+r['variable']+'.json')).read_bytes()).hexdigest()==r['sha256']
names=['S2_Organizational_Participation_2010_DIRECT_v1.csv','S2_2010_QA_v1.md','S2_2010_MEASUREMENT_DICTIONARY_v1.csv','S2_2010_PROVENANCE_v1.csv','S2_2010_2009_CONTINUITY_AUDIT_v1.csv','S2_2010_RUN_LOG.txt','S2_2010_SOURCE_MANIFEST.csv','extract_2010.py','prepare_package.py','verified_variables.json','S2_2010_OFFICIAL_SOURCE_EXCERPTS.txt','S2_2010_DC_QA_v1.csv','S2_2010_ITEM_COUNTS_v1.csv','S2_2010_NATIONAL_QA_v1.csv','QA_checks.json','ATTEMPT1_RUN_LOG.txt','extract_2010_attempt1.py','ATTEMPT1_QA.json']+['API_PEQ5'+x+'.json' for x in 'ABCDE']
(P/'SHA256SUMS.txt').write_text(''.join(hashlib.sha256((P/n).read_bytes()).hexdigest()+'  '+n+'\n' for n in names))
(P/'package_files.json').write_text(json.dumps(names+['SHA256SUMS.txt']))
print(json.dumps({'run_id':L['run_id'],'QA_pass':sum(x['pass'] for x in Q),'QA_total':len(Q),'files':len(names)+1,'report_output_comparison':'PASS'}))
